"""Generated by the QA agent for STORY-106: Browse my transaction history."""
from playwright.sync_api import expect


def test_tc_106_01_first_page_newest_first_api(amira):
    """TC-106-01 (API)"""
    r = amira.get("/api/accounts/CUR-1001/transactions", params={"page": 1})
    assert r.status_code == 200, r.text
    items = r.json()["items"]
    assert len(items) == 10
    dates = [t["date"] for t in items]
    assert dates == sorted(dates, reverse=True)


def test_tc_106_02_every_transaction_exactly_once_api(amira):
    """TC-106-02 (API)"""
    first = amira.get("/api/accounts/CUR-1001/transactions", params={"page": 1}).json()
    ids = []
    for page in range(1, first["pages"] + 1):
        ids += [t["id"] for t in amira.get("/api/accounts/CUR-1001/transactions", params={"page": page}).json()["items"]]
    dupes = sorted({i for i in ids if ids.count(i) > 1})
    assert not dupes, f"transactions repeated across pages: {dupes}"
    assert len(ids) == first["total"] == 25


def test_tc_106_03_page_indicator_ui(signed_in):
    """TC-106-03 (UI)"""
    signed_in.get_by_test_id("nav-history").click()
    expect(signed_in.get_by_test_id("history-page")).to_have_text("Page 1 of 3 · 25 transactions")
    expect(signed_in.get_by_test_id("txn-row")).to_have_count(10)
    signed_in.get_by_test_id("history-next").click()
    expect(signed_in.get_by_test_id("history-page")).to_contain_text("Page 2 of 3")


